# 1. 多项式拟合函数
def poly_func(x, *coeffs):
    return np.polyval(coeffs, x)

# 2. 傅里叶级数拟合函数
def fourier_func(x, a0, a1, b1, a2, b2, a3, b3, a4, b4):
    return a0 + a1*np.cos(x) + b1*np.sin(x) + a2*np.cos(2*x) + b2*np.sin(2*x) + a3*np.cos(3*x) + b3*np.sin(3*x) + a4*np.cos(4*x) + b4*np.sin(4*x)

# 3. 样条插值
spline = interpolate.CubicSpline(theta, r)

# 多项式拟合（6次）
degree = 6
p_coeffs = np.polyfit(theta, r, degree)
poly_fit = np.poly1d(p_coeffs)

# 傅里叶拟合
fourier_guess = [6.8, 0.2, -0.1, 0.05, 0.02, -0.01, 0.005, 0.002, -0.001]
fourier_params, _ = curve_fit(fourier_func, theta, r, p0=fourier_guess, maxfev=10000)

# 计算拟合值
theta_dense = np.linspace(0, 6.28, 1000)
poly_values = poly_func(theta_dense, *p_coeffs)
fourier_values = fourier_func(theta_dense, *fourier_params)
spline_values = spline(theta_dense)

# 计算R²
poly_r2 = r2_score(r, poly_func(theta, *p_coeffs))
fourier_r2 = r2_score(r, fourier_func(theta, *fourier_params))
spline_r2 = r2_score(r, spline(theta))

print("拟合结果评估:")
print(f"多项式拟合 (6次) R² = {poly_r2:.6f}")
print(f"傅里叶拟合 (4阶) R² = {fourier_r2:.6f}")
print(f"样条插值 R² = {spline_r2:.6f}")

# 绘制图像
plt.rcParams['font.family'] = 'SimHei'
plt.figure(figsize=(12, 8))

# 原始数据
plt.plot(theta, r, 'o', markersize=2, alpha=0.6, label='原始数据', color='black')

# 拟合曲线
plt.plot(theta_dense, poly_values, '-', linewidth=2, label=f'多项式拟合 (6次, R²={poly_r2:.4f})', color='red')
plt.plot(theta_dense, fourier_values, '--', linewidth=2, label=f'傅里叶拟合 (4阶, R²={fourier_r2:.4f})', color='blue')
plt.plot(theta_dense, spline_values, '-.', linewidth=2, label=f'样条插值 (R²={spline_r2:.4f})', color='green')

plt.xlabel('极角 (rad)')
plt.ylabel('极径 (mm)')
plt.title('凸轮边缘曲线拟合')
plt.legend()
plt.grid(True, alpha=0.3)
plt.tight_layout()
plt.show()

# 输出拟合方程
print("\n多项式拟合方程 (6次):")
print(f"r(θ) = {p_coeffs[0]:.6f}θ⁶ + {p_coeffs[1]:.6f}θ⁵ + {p_coeffs[2]:.6f}θ⁴ + {p_coeffs[3]:.6f}θ³ + {p_coeffs[4]:.6f}θ² + {p_coeffs[5]:.6f}θ + {p_coeffs[6]:.6f}")

print("\n傅里叶拟合方程 (4阶):")
print(f"r(θ) = {fourier_params[0]:.6f} + {fourier_params[1]:.6f}cos(θ) + {fourier_params[2]:.6f}sin(θ) + {fourier_params[3]:.6f}cos(2θ) + {fourier_params[4]:.6f}sin(2θ) + {fourier_params[5]:.6f}cos(3θ) + {fourier_params[6]:.6f}sin(3θ) + {fourier_params[7]:.6f}cos(4θ) + {fourier_params[8]:.6f}sin(4θ)")